const body = $json.body || {};
const name = String(body.name || '').trim();
const contact = String(body.contact || '').trim();
const mode = body.mode === 'media' ? 'media' : 'topic';

if (!name || !contact) {
  throw new Error('필수값 누락: 이름/연락처가 비어있습니다.');
}
if (body.termsConsent !== true) {
  throw new Error('이용약관 동의가 필요합니다.');
}
if (mode === 'topic' && !String(body.topic || '').trim()) {
  throw new Error('필수값 누락: 주제가 비어있습니다.');
}
if (mode === 'media' && !String(body.driveLink || '').trim()) {
  throw new Error('필수값 누락: 드라이브 폴더 링크가 비어있습니다.');
}

// ID를 "년월일시분초"(YYMMDDHHmmss, 12자리) 형식으로 생성 - 기존 시트 행들의 ID 규칙과 동일하게 맞춤
// KST(한국 시간) 기준으로 생성
const nowKST = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Seoul' }));
const pad = (n) => String(n).padStart(2, '0');
const MAX_NOTE_LEN = 500;
const MAX_TOPIC_LEN = 300;

const ID = [
  String(nowKST.getFullYear()).slice(2),
  pad(nowKST.getMonth() + 1),
  pad(nowKST.getDate()),
  pad(nowKST.getHours()),
  pad(nowKST.getMinutes()),
  pad(nowKST.getSeconds())
].join('');

// 시트 행으로 조립 — 두 모드 모두 Status='기획'에서 시작 (공통 대본 생성 모듈 / MyMediaFolder 분석 모듈이 각자 조건에 맞는 행만 집어감)
const row = {
  ID,
  Target: '전체대상',
  Status: '기획',
  Form: '쇼츠',
  신청자이메일: contact,
  신청자이름: name,
  결제완료: 'FALSE', // 웹으로 들어온 신청은 결제 확인 전까지 항상 테스트(저비용) 화질로 시작 (안전)
};

if (mode === 'topic') {
  row.Subtopic = String(body.topic || '').trim().slice(0, MAX_TOPIC_LEN);
  row.Keyword = '웹신청';

  // [신규] 고급 옵션 (선택사항) - 입력 안 하면 그냥 기존 자동 로직이 처리
  if (body.target) row.Target = String(body.target).trim();
  if (body.productLink) row.제품링크 = String(body.productLink).trim();
  if (body.form) row.Form = String(body.form).trim();
  if (body.directorNote) row.연출지시 = String(body.directorNote).trim().slice(0, MAX_NOTE_LEN);
  if (body.tempo) row.템포 = String(body.tempo).trim();

  // 성별/연령대는 시트의 Voice(이름) 컬럼 체계를 그대로 활용:
  // 대표 보이스 이름 하나로 매핑해서 넣어주면, 기존 성별매핑 로직이 알아서 처리함
  if (body.voiceGender === '여성') row.Voice = 'Sarah';
  else if (body.voiceGender === '남성') row.Voice = 'Daniel';
  if (body.voiceAge) row.VoiceAge = String(body.voiceAge).trim();
} else {
  row.MyMediaFolder = String(body.driveLink || '').trim();
  // [수정] 이 파이프라인은 연출지시가 아니라 Subtopic을 "톤/맥락 힌트"로 읽으므로 Subtopic에 매핑
  row.Subtopic = String(body.mediaNote || '').trim().slice(0, MAX_NOTE_LEN);

  if (body.voiceGender === '여성') row.Voice = 'Sarah';
  else if (body.voiceGender === '남성') row.Voice = 'Daniel';
  if (body.voiceAge) row.VoiceAge = String(body.voiceAge).trim();
}

return [{ json: row }];

const body = $('웹 신청 접수 Webhook').item.json.body || {};
const tokenInfo = $json; // tokeninfo 응답 (실패 시 error 필드 포함)
const GOOGLE_CLIENT_ID = '188637268860-9hj2af4bt8esn506bf5bqs72qnbu0qjs.apps.googleusercontent.com';

const 유효함 =
  tokenInfo &&
  !tokenInfo.error &&
  tokenInfo.aud === GOOGLE_CLIENT_ID &&
  tokenInfo.email &&
  String(tokenInfo.email_verified) === 'true';

if (!유효함) {
  throw new Error('구글 로그인 검증에 실패했습니다. 로그인 후 다시 시도해주세요.');
}

// 검증된 이메일/이름만 신뢰하고 사용 (body에 있는 값은 조작 가능하므로 무시)
return [{
  json: {
    body: {
      ...body,
      name: tokenInfo.name || body.name || '',
      contact: tokenInfo.email
    }
  }
}];

const MAX_FREE_TRIALS = 3;
const email = $('검증 결과 확인 (aud/이메일)').item.json.body.contact;
const rows = $input.all().map(item => item.json);

const 기존신청수 = rows.filter(r => (r.신청자이메일 || '').trim().toLowerCase() === email.trim().toLowerCase()).length;

if (기존신청수 >= MAX_FREE_TRIALS) {
  throw new Error('무료체험은 이메일당 최대 ' + MAX_FREE_TRIALS + '회까지 가능합니다. 계속 이용하시려면 결제가 필요해요.');
}

return [{ json: $('검증 결과 확인 (aud/이메일)').item.json }];
